import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.D7Ov6LBE.js";const p=JSON.parse('{"title":"Orquestração de Agentes de IA","description":"","frontmatter":{},"headers":[],"relativePath":"engenharia/orquestracao-agentes.md","filePath":"engenharia/orquestracao-agentes.md","lastUpdated":1786474711000}'),s={name:"engenharia/orquestracao-agentes.md"};function n(i,e,d,l,c,g){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="orquestracao-de-agentes-de-ia" tabindex="-1">Orquestração de Agentes de IA <a class="header-anchor" href="#orquestracao-de-agentes-de-ia" aria-label="Permalink to &quot;Orquestração de Agentes de IA&quot;">​</a></h1><p>Como o projeto é desenvolvido com auxílio de agentes de IA — convenções, contexto unificado e rotinas.</p><h2 id="contexto-unificado-de-agentes" tabindex="-1">Contexto unificado de agentes <a class="header-anchor" href="#contexto-unificado-de-agentes" aria-label="Permalink to &quot;Contexto unificado de agentes&quot;">​</a></h2><p><strong>Arquivo:</strong> <code>docs/orquestracao_agentes/CONTEXTO_UNIFICADO_AGENTES.md</code></p><p>O projeto mantém um documento de contexto unificado para orquestrar agentes de IA no desenvolvimento:</p><ul><li><strong>Estado do projeto</strong> — o que está implementado, o que está em andamento, decisões tomadas.</li><li><strong>Padrões obrigatórios</strong> — arquitetura, nomenclatura, validações.</li><li><strong>Rotinas</strong> — sequência de execução (verificar → planejar → implementar → validar).</li><li><strong>Prevenção de regressão</strong> — o que não pode quebrar (funcionalidade fiscal, offline, export).</li></ul><h2 id="regras-base-agents-md" tabindex="-1">Regras base (AGENTS.md) <a class="header-anchor" href="#regras-base-agents-md" aria-label="Permalink to &quot;Regras base (AGENTS.md)&quot;">​</a></h2><p>O <code>AGENTS.md</code> na raiz define as regras para agentes que trabalham no repo:</p><table tabindex="0"><thead><tr><th>Regra</th><th>Detalhe</th></tr></thead><tbody><tr><td><strong>Padrões do projeto</strong></td><td>Seguir SoC, tipagem estrita, contratos em <code>types.ts</code></td></tr><tr><td><strong>Validação</strong></td><td>Rodar lint/build antes de concluir</td></tr><tr><td><strong>Ordem de execução</strong></td><td>Contexto unificado → plano → implementação → verificação</td></tr><tr><td><strong>Não quebrar</strong></td><td>Motor fiscal, offline-first, sync e export</td></tr></tbody></table><h2 id="boas-praticas-ao-delegar-para-agentes" tabindex="-1">Boas práticas ao delegar para agentes <a class="header-anchor" href="#boas-praticas-ao-delegar-para-agentes" aria-label="Permalink to &quot;Boas práticas ao delegar para agentes&quot;">​</a></h2><ol><li><strong>Sempre passar o contexto unificado</strong> — o agente não tem memória da conversa.</li><li><strong>Pedir verificação executável</strong> — build/lint/test, não &quot;deve funcionar&quot;.</li><li><strong>Mudanças pequenas e auditáveis</strong> — cada avanço em commit próprio.</li><li><strong>Revisar diffs com foco em regressão</strong> — fiscal e offline são críticos.</li></ol><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./boas-praticas">Boas Práticas de Engenharia</a></li><li><a href="./diagnostico-roadmap">Diagnóstico &amp; Roadmap</a></li><li><a href="./../docs-legados/indice">Contexto unificado (docs)</a></li></ul>',13)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
